358	/// Replaces `entry`'s props and `composes` with the checker's, keeping a description or tags only the structural pass
359	/// has, for the whole-project merge. Facts are read as [`merge_semantic_props`] reads them, from `syntax` and as
360	/// `resolver` allows. The checker's props are laid out in the layers `cx` decides ([`layer_checker_props`]).
361	#[allow(clippy::too_many_arguments)]
362	fn apply_props(
363	    entry: &mut ComponentEntry,
364	    semantic: &SemanticComponent,
365	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
366	    memo: &mut MergeMemo,
367	    syntax: &SourceSyntax,
368	    resolver: ResolverFacts,
369	    cx: CollapseContext,
370	) -> MergedProps {
371	    // The whole-project merge replaces the props and leaves `@types/react`'s to the inheritance layers. A component
372	    // with no layer has nowhere to leave them: a context's `Provider` (`value`, `children`) or a `th`/`td` attribute
373	    // intersection names no element. Its `@types/react` props the structural pass lists stay, as the curated mode
374	    // keeps them (`targets_of` asks the checker for those names only, `key` among them only if the component lists it).
375	    let layered = !entry.inheritance.is_empty();
376	    let own: Vec<&Arc<SemanticProp>> = semantic
377	        .props
378	        .iter()
379	        .filter(|prop| !prop.react_declared || (!layered && entry.props.contains_key(&prop.name)))
380	        .collect();
381	    let (own, notable) = layer_checker_props(entry, own, &semantic.whole, cx);
382	    let merge = Merge { composes: semantic.composes.as_deref(), unanswered: Unanswered::Drop, syntax, resolver };
383	    let merged = replace_props(entry, own.into_iter(), &merge, shared, memo);
384	    move_notable(entry, &notable);
