388	/// The checker's `props` for `entry` without those an inherited source collapsed into a layer holds, and the notable
389	/// ones to move to `notableInherited` once merged ([`move_notable`]).
390	///
391	/// The collapse decision has one owner, [`CollapseInheritedProps::collapses`](crate::types::options::CollapseInheritedProps::collapses),
392	/// asked with the members of a source that reach the component. The structural resolver decides the sources it reads,
393	/// which are its layers here; a source the structural answer did not read (no structural prop and no layer has it as
394	/// its source) is decided by `cx` ([`CollapseContext::collapses`]). [`Layering::kept`] makes the same decision from a
395	/// [`LayerFacts`] of `entry`, before the answer's types are converted.
396	///
397	/// 1. A prop a collapsed layer holds, by (source, name): its `parent` is the layer's source and the layer names it
398	///    (`InheritedLayer::members`), is left to it, unless the structural answer lists the prop itself (the component
399	///    declares it again), or it is one of the layer's notable members: that one is merged as any prop is (the
400	///    component's default, the checker's type and JSDoc) and then moved to `notableInherited`, replacing the structural
401	///    entry, as for a layer made here. A prop of the same name another source declares is not the layer's: it is kept.
402	/// 2. A source only the checker read becomes a collapsed layer only when the checker proved the props type reaches it
403	///    whole (`whole`, [`SemanticComponent::whole`]) and the owner collapses it, asked with the members that reach the
404	///    component: the props of the answer whose `parent` is the source, each name once (the structural resolver counts
405	///    the same; no declared count is asked of the checker). Never hide on silence: a source reached through a `Pick`, a
406	///    mapped type, a project alias of either, a conditional or a union, or one the checker said nothing of, is listed,
407	///    whatever its size. `members` are those that reach and `totalProps` their number, what the layer holds. Its notable
408	///    props move to `notableInherited`, as the structural resolver keeps a collapsed source's notable members.
409	pub(crate) fn layer_checker_props<'a>(
410	    entry: &mut ComponentEntry,
411	    props: Vec<&'a Arc<SemanticProp>>,
412	    whole: &[PropParent],
413	    cx: CollapseContext,
414	) -> (Vec<&'a Arc<SemanticProp>>, Vec<(String, PropParent)>) {
415	    // The notable members of the layers the entry has (rule 1), then those of the layers made here (rule 2).
416	    let of_entry = layer_notable(entry);
417	    let (layers, made) = checker_sources(
418	        &*entry,
419	        props.iter().map(|prop| (prop.name.as_str(), prop.parent.as_ref(), prop.react_declared)),
420	        whole,
421	        cx,
422	    );
423	    entry.inheritance.extend(layers);
424	    let layered: Held<'_> = entry
425	        .inheritance
426	        .iter()
427	        .flat_map(|layer| {
428	            layer.members.iter().map(|name| (name.as_str(), layer.type_name.as_str(), layer.file_name.as_str()))
429	        })
430	        .collect();
431	    let unconverted = unconverted_type();
432	    let kept: Vec<&'a Arc<SemanticProp>> = props
433	        .into_iter()
434	        .filter(|prop| {
435	            layered.is_empty()
436	                || keeps(
437	                    &prop.name,
438	                    prop.parent.as_ref(),
439	                    (&of_entry, &made),
440	                    entry.props.contains_key(&prop.name),
441	                    &layered,
442	                )
443	        })
444	        .collect();
445	    // A kept notable member of a layer the entry has is merged over its structural entry (of that same source), which
446	    // keeps a description or tags only the structural pass has; `move_notable` moves the merged prop back.
447	    for (name, source) in &of_entry {
448	        if kept.iter().any(|prop| prop.name == *name && prop.parent.as_ref() == Some(source))
449	            && !entry.props.contains_key(name)
450	            && entry.notable_inherited.get(name).is_some_and(|structural| structural.parent.as_ref() == Some(source))
451	            && let Some(structural) = entry.notable_inherited.remove(name)
452	        {
453	            entry.props.insert(name.clone(), structural);
454	        }
455	    }
456	    let mut notable = of_entry;
457	    notable.extend(made);
458	    // A prop the checker left unconverted is one this decision leaves to a layer ([`Layering::kept`]). Keeping one means
459	    // the target's layering was made from another structural answer or context than this merge's: it is never merged
460	    // as a type, so the structural prop stays.
461	    debug_assert!(
462	        kept.iter().all(|prop| prop.prop_type != unconverted),
463	        "the merge keeps a prop the checker left to a layer: the target's layering is not this merge's"
464	    );
465	    let kept = kept.into_iter().filter(|prop| prop.prop_type != unconverted).collect();
466	    (kept, notable)
467	}
