469	/// What the structural answer says of a component that decides which of the checker's props a collapsed layer takes
470	/// (the merge's `layer_checker_props`): the props it lists, the source each names (`parent`), and its inheritance layers, their
471	/// sources and members. A [`SemanticTarget`] carries it in a [`Layering`], so the checker can leave unconverted what the
472	/// merge leaves to a layer.
473	#[derive(Debug, Clone, Default, PartialEq, Eq, Hash)]
474	pub struct LayerFacts {
475	    /// The names of the props the structural answer lists.
476	    listed: std::collections::BTreeSet<String>,
477	    /// The `parent` of each prop it lists, each once.
478	    parents: Vec<PropParent>,
479	    /// Each inheritance layer's source, by type name and file.
480	    sources: Vec<(String, String)>,
481	    /// The members of every inheritance layer, each by (name, the layer's type name, its file) ([`Held`]).
482	    members: std::collections::BTreeSet<(String, String, String)>,
483	    /// The notable members of its collapsed layers it does not list, with their source ([`layer_notable`]).
484	    notable: Vec<(String, PropParent)>,
485	}
486	
487	/// The notable members (`className`, `style`, …) of `entry`'s collapsed layers that it does not list itself, each with
488	/// its layer's source: the merge merges the checker's answer for each and moves it back to `notableInherited`.
489	fn layer_notable(entry: &ComponentEntry) -> Vec<(String, PropParent)> {
490	    let notable_names = crate::react_types::notable_html_attrs("");
491	    entry
492	        .inheritance
493	        .iter()
494	        .filter(|layer| layer.html_element.is_none())
495	        .flat_map(|layer| {
496	            layer
497	                .members
498	                .iter()
499	                .filter(|name| notable_names.contains(&name.as_str()) && !entry.props.contains_key(*name))
500	                .map(|name| {
501	                    (name.clone(), PropParent { name: layer.type_name.clone(), file_name: layer.file_name.clone() })
502	                })
503	        })
504	        .collect()
505	}
