507	impl LayerFacts {
508	    /// What `entry`, a structural answer, says.
509	    pub fn of(entry: &ComponentEntry) -> Self {
510	        let mut parents: Vec<PropParent> = Vec::new();
511	        for parent in entry.props.values().filter_map(|prop| prop.parent.as_ref()) {
512	            if !parents.contains(parent) {
513	                parents.push(parent.clone());
514	            }
515	        }
516	        Self {
517	            listed: entry.props.keys().cloned().collect(),
518	            parents,
519	            sources: entry.inheritance.iter().map(|layer| (layer.type_name.clone(), layer.file_name.clone())).collect(),
520	            members: entry
521	                .inheritance
522	                .iter()
523	                .flat_map(|layer| {
524	                    layer.members.iter().map(|name| (name.clone(), layer.type_name.clone(), layer.file_name.clone()))
525	                })
526	                .collect(),
527	            notable: layer_notable(entry),
528	        }
529	    }
