619	/// The layers a checker's answer adds to `structural`'s, and the notable props they hold, to move to
620	/// `notableInherited` ([`layer_checker_props`]'s second rule). `props` are the answer's, by name, `parent` and whether
621	/// `@types/react` declares it, in its order. Only a source in `whole` can become a layer (the second rule).
622	fn checker_sources<'p>(
623	    structural: &impl Structural,
624	    props: impl Iterator<Item = (&'p str, Option<&'p PropParent>, bool)>,
625	    whole: &[PropParent],
626	    cx: CollapseContext,
627	) -> (Vec<InheritedLayer>, Vec<(String, PropParent)>) {
628	    // Each source the answer names (a prop's `parent` is an interface), in the order it first names it, with the
629	    // members of it that reach the component, each once.
630	    let mut sources: Vec<(&'p PropParent, Vec<String>)> = Vec::new();
631	    for (name, parent, react_declared) in props {
632	        let Some(parent) = parent.filter(|_| !react_declared) else { continue };
633	        match sources.iter_mut().find(|(source, _)| *source == parent) {
634	            Some((_, names)) if !names.iter().any(|member| member == name) => names.push(name.to_string()),
635	            Some(_) => {}
636	            None => sources.push((parent, vec![name.to_string()])),
637	        }
638	    }
639	    let notable_names = crate::react_types::notable_html_attrs("");
640	    let mut notable = Vec::new();
641	    let mut layers = Vec::new();
642	    for (source, members) in sources {
643	        // The one rule: a source the structural answer did not read collapses only when the checker proved the props
644	        // type reaches it whole. Not proven (a selection on the way, or nothing said), it is listed.
645	        if structural.reads(source)
646	            || !whole.contains(source)
647	            || !cx.collapses(&source.file_name, &source.name, members.len())
648	        {
649	            continue;
650	        }
651	        notable.extend(
652	            members
653	                .iter()
654	                .filter(|name| notable_names.contains(&name.as_str()))
655	                .map(|name| (name.clone(), source.clone())),
656	        );
657	        layers.push(InheritedLayer {
658	            type_name: source.name.clone(),
659	            file_name: source.file_name.clone(),
660	            omitted: Vec::new(),
661	            html_element: None,
662	            total_props: u32::try_from(members.len()).unwrap_or(u32::MAX),
663	            members,
664	        });
665	    }
666	    (layers, notable)
667	}
