669	/// A notable prop's name and the collapsed source it belongs to.
670	type Notable = (String, PropParent);
671	
672	/// The members of collapsed layers, each by (name, the layer's type name, its file): a layer holds a prop only when the
673	/// prop's `parent` is the layer's source, never by its name alone.
674	type Held<'a> = rustc_hash::FxHashSet<(&'a str, &'a str, &'a str)>;
675	
676	/// Whether the merge keeps a checker prop named `name` declared in `parent`: a notable member of a layer the entry has
677	/// or the answer adds whose source is `parent` (`notable.0`, [`layer_notable`]; `notable.1`), a prop the structural
678	/// answer lists itself (`listed`), or one no layer holds as a member of its own source (`layered`). A prop with no
679	/// `parent` is no source's member, so no layer holds it.
680	fn keeps(
681	    name: &str,
682	    parent: Option<&PropParent>,
683	    notable: (&[Notable], &[Notable]),
684	    listed: bool,
685	    layered: &Held<'_>,
686	) -> bool {
687	    let (of_entry, made) = notable;
688	    let of_source = |(notable, source): &Notable| notable == name && parent == Some(source);
689	    made.iter().any(of_source)
690	        || of_entry.iter().any(of_source)
691	        || listed
692	        || !parent.is_some_and(|parent| layered.contains(&(name, parent.name.as_str(), parent.file_name.as_str())))
693	}
694	
695	/// Moves each merged prop `notable` names from `entry`'s props to its `notableInherited`, when it is the collapsed
696	/// source's member (its `parent` is that source); a prop of that name the component declares itself stays a prop.
697	pub(crate) fn move_notable(entry: &mut ComponentEntry, notable: &[(String, PropParent)]) {
698	    for (name, source) in notable {
699	        if entry.props.get(name).is_some_and(|prop| prop.parent.as_ref() == Some(source))
700	            && let Some(prop) = entry.props.remove(name)
701	        {
702	            entry.notable_inherited.insert(name.clone(), prop);
703	        }
704	    }
705	}
