707	/// What one merged prop was made from, by identity: the checker's prop, the structural prop of the same name, the
708	/// union a prop without a `parent` writes in the entry's file (a prop with one finds it by itself) and the code
709	/// default, each by address (`0` for none). The first two are shared copies
710	/// (the backend's and the resolver's interners), so the components of a design system that share a prop share its key.
711	type MergeKey = (usize, usize, (usize, usize), usize);
712	
713	/// The props one merge has made, by what they were made from ([`MergeKey`]). A merged prop is a function of those
714	/// inputs and the merge's [`ResolverFacts`] alone, so a prop made from the same ones is the one made before: it skips
715	/// the copy, the reordering and the interning of a type that is often hundreds of members wide. Each entry holds the
716	/// two props its key points at, so neither is freed and its address taken by another prop while the merge runs.
717	#[derive(Default)]
718	struct MergeMemo {
719	    made: FxHashMap<MergeKey, MemoEntry>,
720	}
721	
722	struct MemoEntry {
723	    _semantic: Arc<SemanticProp>,
724	    _structural: Option<Arc<ParsedProp>>,
725	    merged: Arc<ParsedProp>,
726	    unread: bool,
