const cfg = ts.readConfigFile(path.join(proj, 'tsconfig.json'), ts.sys.readFile).config;
const parsed = ts.parseJsonConfigFileContent(cfg, ts.sys, proj);
const program = ts.createProgram(files, parsed.options);
const checker = program.getTypeChecker();
