  let p = decl.parent;
  if (ts.isInterfaceDeclaration(p) || ts.isClassDeclaration(p)) return p.name.text;
  if (ts.isTypeLiteralNode(p) && ts.isTypeAliasDeclaration(p.parent)) return p.parent.name.text;
  if (ts.isMappedTypeNode(p)) return null;
  return null;
}
