  const sf = program.getSourceFile(file);
  const id = path.basename(file, '.tsx').slice(2);
  const alias = sf.statements.find((s) => ts.isTypeAliasDeclaration(s) && s.name.text === `Props_${id}`);
  const type = checker.getTypeAtLocation(alias.name);
  const parts = type.isUnion() ? type.types : [type];
  const props = new Map();
  for (const part of parts) {
    for (const sym of checker.getPropertiesOfType(checker.getApparentType(part))) {
      const name = sym.getName();
