        const f = d.getSourceFile().fileName;
        return { parent: parentOf(d), file: f, own: f === file, react: /@types\/react|csstype/.test(f) };
      });
      if (!props.has(name)) props.set(name, { name, decls, optional: !!(sym.flags & ts.SymbolFlags.Optional) });
    }
  }
