"""Re-judge out/*.json (from gen.py) with the layer contract: a notable member of a collapsed layer of the same source
is that member's resolved copy, not a duplicate. Scratch."""
import json, sys, collections, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).parent))
import gen

ROOT = gen.ROOT
truth = gen.oracle(ROOT / "projects/g")
rows = []
lanes_by = collections.defaultdict(dict)
for mode in ("dependencies", "all", "none"):
    for lane in "SMC":
        comps = gen.components(json.load(open(ROOT / "out" / f"{mode}-{lane}.json")))
        for cname, t in sorted(truth.items()):
            c = comps.get(cname)
            if c is None:
                rows.append((mode, lane, cname, "MISSING", ""))
                continue
            lanes_by[(mode, cname)][lane] = gen.collapsed(c)
            reach = {p["name"]: p for p in t["props"]}
            props, notable, layers = c["props"], c["notableInherited"], c["inheritance"]
            held = collections.defaultdict(list)
            for layer in layers:
                for m in layer["members"]:
                    held[m].append(layer["typeName"])
                    if m not in reach:
                        rows.append((mode, lane, cname, "LAYER_MEMBER_NOT_REACHING", f"{layer['typeName']}.{m}"))
                    elif layer["typeName"] not in {d["parent"] for d in reach[m]["decls"]}:
                        rows.append((mode, lane, cname, "LAYER_HOLDS_OVERRIDDEN_PROP", f"{layer['typeName']}.{m} (declared by {sorted(d['parent'] or 'literal' for d in reach[m]['decls'])})"))
            for name, p in reach.items():
                react = all(d["react"] for d in p["decls"])
                own = any(d["own"] for d in p["decls"])
                nparent = (notable.get(name) or {}).get("parent") or {}
                notable_is_layer_copy = name in notable and nparent.get("name") in held[name]
                places = (name in props) + (name in notable and not notable_is_layer_copy) + len(set(held[name]))
                if react and not own:
                    if places > 1:
                        rows.append((mode, lane, cname, "DUP_REACT", name))
                    continue
                if places == 0:
                    rows.append((mode, lane, cname, "LOSS_OWN" if own else "LOSS", name))
                elif len(set(held[name])) > 1 and name not in props:
                    rows.append((mode, lane, cname, "IN_TWO_LAYERS", f"{name} {held[name]}"))
                elif places > 1:
                    where = [w for w, x in (("list", name in props), ("notable", name in notable and not notable_is_layer_copy), ("layer:" + ",".join(held[name]), held[name])) if x]
                    rows.append((mode, lane, cname, "DUP", f"{name} in {'+'.join(where)}"))
                if own and name in notable:
                    rows.append((mode, lane, cname, "OWN_AS_NOTABLE", name))
            for name in list(props) + list(notable):
                if name not in reach and name != "ref":
                    rows.append((mode, lane, cname, "PHANTOM", name))
            # destructuring defaults: className and a3 in the `defaults` components
            if "Dflt" in cname or cname == "C_dflt":
                cn = props.get("className") or notable.get("className") or {}
                a3 = props.get("a3") or notable.get("a3")
                rows.append((mode, lane, cname, "DEFAULT_CHECK", f"className.default={cn.get('defaultValue')!r} a3={'listed default=' + repr(a3.get('defaultValue')) if a3 else 'in layer, default dropped'}"))
for (mode, cname), l in lanes_by.items():
    if len({json.dumps(v) for v in l.values()}) > 1:
        rows.append((mode, "SMC", cname, "LANE_DISAGREE", json.dumps(l)))
json.dump(rows, open(ROOT / "rows.json", "w"), indent=0)
agg = collections.defaultdict(lambda: collections.defaultdict(list))
for mode, lane, cname, cls, d in rows:
    agg[(cname, cls)][f"{mode[:3]}/{lane}"].append(d)
for (cname, cls), v in sorted(agg.items()):
    sample = next(iter(v.values()))
    print(cname, cls, " ".join(f"{k}:{len(x)}" for k, x in sorted(v.items())), "|", "; ".join(sample[:3])[:230])

