"""Incidence and size cost of the red-team classes on corpus outputs (corpus.sh). Scratch.

For each component (merged lane M, and structural S for the own-over-React class):
- collapsed layers (members non-empty), and for each whether the proposed allow-list proves it:
  P1 the source is not a type-literal alias the checker names no parent for (listed members with parent None that a
     layer of the component holds by name);
  P2 no member is redeclared: no listed or notable prop of the same name with a different parent, and no second layer
     holds the name;
  P3 no member name is also declared by @types/react (a React-declared listed name anywhere in the corpus, or an
     attribute of an element layer);
- REACT_OWN_DROPPED: a prop S lists with a non-React parent that M lists nowhere (not list, notable or layer) while
  the component has an element layer.
"""
import json, sys, collections, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).parent))
import gen

D = pathlib.Path(__file__).parent / "corpus"
for name in ("gate-large", "chakra-only", "shadcn-ui"):
    M = gen.components(json.load(open(D / f"M-{name}.json")))
    S = gen.components(json.load(open(D / f"S-{name}.json")))
    react_names = set()
    for out in (M, S):
        for c in out.values():
            for p in list(c["props"].values()) + list(c["notableInherited"].values()):
                if "/@types/react/" in ((p.get("parent") or {}).get("fileName") or ""):
                    react_names.add(p["name"])
    stats = collections.Counter()
    moved = collections.Counter()
    examples = collections.defaultdict(list)
    for cname, c in M.items():
        layers = [l for l in c["inheritance"] if l["members"] and not l.get("htmlElement")]
        if layers:
            stats["components_with_collapsed_layer"] += 1
        fail_any = set()
        held = collections.Counter(m for l in layers for m in set(l["members"]))
        for l in layers:
            members = set(l["members"])
            listed = {n: p for n, p in c["props"].items() if n in members}
            p1 = [n for n, p in listed.items() if not p.get("parent")]
            p2 = [n for n, p in listed.items() if p.get("parent") and p["parent"]["name"] != l["typeName"]]
            p2 += [n for n in members if held[n] > 1]
            p2 += [n for n, p in c["notableInherited"].items() if n in members and (p.get("parent") or {}).get("name") not in (l["typeName"], None)]
            p3 = [n for n in members if n in react_names]
            for tag, xs in (("P1_alias_dup", p1), ("P2_redeclared", p2), ("P3_react_name", p3)):
                if xs:
                    fail_any.add(tag)
                    moved[tag] += len(set(xs))
                    if len(examples[tag]) < 3:
                        examples[tag].append(f"{cname}:{l['typeName']}:{sorted(set(xs))[:4]}")
        for tag in fail_any:
            stats[f"components_failing_{tag}"] += 1
        if fail_any:
            stats["components_failing_any"] += 1
            stats["layers_members_if_listed_whole"] += sum(len(l["members"]) for l in layers)
        # own (non-React) props the structural lane lists that the merge drops when an element layer exists
        s = S.get(cname)
        if s and any(l.get("htmlElement") for l in c["inheritance"]):
            inm = set(c["props"]) | set(c["notableInherited"]) | set(held)
            lost = [n for n, p in s["props"].items() if n not in inm and "/node_modules/" not in ((p.get("parent") or {}).get("fileName") or "/node_modules/")]
            lost_parentless = [n for n, p in s["props"].items() if n not in inm and not p.get("parent")]
            lost = sorted(set(lost) | set(lost_parentless))
            if lost:
                stats["components_REACT_OWN_DROPPED"] += 1
                stats["props_REACT_OWN_DROPPED"] += len(lost)
                if len(examples["REACT_OWN_DROPPED"]) < 4:
                    examples["REACT_OWN_DROPPED"].append(f"{cname}:{lost[:5]}")
    print(f"== {name}: {len(M)} components")
    for k, v in sorted(stats.items()):
        print(f"  {k}: {v}")
    for k, v in sorted(moved.items()):
        print(f"  members_to_list_per_member_{k}: {v}")
    for k, v in examples.items():
        print(f"  e.g. {k}: {v}")

